'use strict';
const crypto=require('node:crypto');
const {validateContent}=require('../lib/content-schema.cjs');
const REPO='wesleyussene/TPS-TECH', BRANCH='main', FILE='dist/content.json';
const attempts=new Map();
const error=(message,status=400)=>Object.assign(new Error(message),{status});
function configured(){return !!(process.env.ADMIN_PASSWORD_HASH&&process.env.ADMIN_SESSION_SECRET?.length>=32&&process.env.GITHUB_CONTENT_TOKEN);}
function equal(a,b){const x=Buffer.from(a),y=Buffer.from(b);return x.length===y.length&&crypto.timingSafeEqual(x,y);}
function sign(value){return crypto.createHmac('sha256',process.env.ADMIN_SESSION_SECRET+process.env.ADMIN_PASSWORD_HASH).update(value).digest('base64url');}
function session(req){const token=(req.headers.cookie||'').split(';').map(s=>s.trim()).find(s=>s.startsWith('__Host-ts_admin='))?.slice(16);if(!token)return false;const [data,sig]=token.split('.');if(!sig||!equal(sign(data),sig))return false;try{const p=JSON.parse(Buffer.from(data,'base64url'));return p.exp>Date.now()&&p.exp<Date.now()+9*3600000;}catch{return false;}}
function passwordMatches(password){if(typeof password!=='string'||password.length>256)return false;const [salt,expected]=process.env.ADMIN_PASSWORD_HASH.split(':');if(!/^[a-f0-9]{32}$/.test(salt||'')||!/^[a-f0-9]{128}$/.test(expected||''))return false;return equal(crypto.scryptSync(password,salt,64).toString('hex'),expected);}
async function github(path,method='GET',body){const result=await fetch('https://api.github.com/repos/'+REPO+path,{method,headers:{Authorization:'Bearer '+process.env.GITHUB_CONTENT_TOKEN,Accept:'application/vnd.github+json','X-GitHub-Api-Version':'2022-11-28','Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(18000)});if(!result.ok){if([409,422].includes(result.status))throw error('O site foi alterado entretanto. Guarde o rascunho, carregue a versão actual e reveja as alterações.',409);throw error(result.status===401||result.status===403?'A ligação de publicação precisa de ser renovada pelo administrador.':'Não foi possível comunicar com o armazenamento. Tente novamente.',502);}return result.json();}
async function current(){const ref=await github('/git/ref/heads/'+BRANCH);const head=ref.object.sha;const file=await github('/contents/'+FILE+'?ref='+head);if(file.encoding!=='base64')throw error('Conteúdo demasiado grande.',502);return {head,content:JSON.parse(Buffer.from(file.content,'base64').toString('utf8'))};}
function assetsFor(input,content){if(!Array.isArray(input)||input.length>30)throw error('Carregue no máximo 30 imagens por publicação.');const references=new Set([content.hero.image,...content.banners.map(b=>b.image),...content.products.flatMap(p=>[p.image,...p.images])]);return input.filter(a=>references.has(a.path)).map(a=>{if(!/^assets\/uploads\/[a-f0-9]{64}\.webp$/.test(a.path)||typeof a.data!=='string'||!/^[A-Za-z0-9+/]*={0,2}$/.test(a.data))throw error('Imagem inválida.');const bytes=Buffer.from(a.data,'base64');if(bytes.length>450000||bytes.length<12||bytes.toString('ascii',0,4)!=='RIFF'||bytes.toString('ascii',8,12)!=='WEBP'||crypto.createHash('sha256').update(bytes).digest('hex')!==a.path.split('/').pop().split('.')[0])throw error('Imagem inválida ou demasiado grande.');return {path:'dist/'+a.path,mode:'100644',type:'blob',bytes};});}
async function publish(body){const content=validateContent(body.content);if(!/^[a-f0-9]{40}$/.test(body.base||''))throw error('Recarregue o conteúdo antes de publicar.');const ref=await github('/git/ref/heads/'+BRANCH);if(ref.object.sha!==body.base)throw error('Existe uma versão mais recente. Guarde o rascunho e carregue o conteúdo actual antes de publicar.',409);const parent=await github('/git/commits/'+body.base);const assets=assetsFor(body.assets||[],content);const entries=[];for(const a of assets){const blob=await github('/git/blobs','POST',{content:a.bytes.toString('base64'),encoding:'base64'});entries.push({path:a.path,mode:a.mode,type:a.type,sha:blob.sha});}
 const json=JSON.stringify(content,null,2)+'\n';const script='/* Generated by the admin panel. Edit at /admin.html. */\nwindow.TOP_CONTENT = '+JSON.stringify(content).replace(/</g,'\\u003c')+';\nwindow.TOP_PRODUCTS = window.TOP_CONTENT.products.filter(p => p.active !== false);\n';
 entries.push({path:FILE,mode:'100644',type:'blob',content:json},{path:'dist/products.js',mode:'100644',type:'blob',content:script});
 const tree=await github('/git/trees','POST',{base_tree:parent.tree.sha,tree:entries});const commit=await github('/git/commits','POST',{message:'Update storefront content from admin panel',tree:tree.sha,parents:[body.base]});await github('/git/refs/heads/'+BRANCH,'PATCH',{sha:commit.sha,force:false});return {head:commit.sha,message:'Alterações enviadas para publicação. O site será actualizado quando a publicação terminar.'};}
module.exports=async(req,res)=>{res.setHeader('Cache-Control','no-store');res.setHeader('X-Content-Type-Options','nosniff');const send=(status,data)=>res.status(status).json(data);try{if(!configured())return send(503,{error:'O painel está instalado. Falta activar o acesso seguro e a ligação de publicação nas definições do servidor.',setupRequired:true});if(req.method==='GET'){if(!session(req))return send(401,{error:'Entre para gerir o site.'});return send(200,await current());}if(req.method!=='POST')return send(405,{error:'Método não permitido.'});const allowed=(process.env.ADMIN_ORIGIN||'https://www.topsolution.co.mz,https://topsolution.co.mz').split(',');if(!allowed.includes(req.headers.origin)||!req.headers['content-type']?.startsWith('application/json'))return send(403,{error:'Pedido não autorizado.'});let body=req.body;if(typeof body==='string'){if(Buffer.byteLength(body)>3900000)throw error('Publique menos imagens de cada vez.',413);body=JSON.parse(body);}if(!body||Buffer.byteLength(JSON.stringify(body))>3900000)throw error('Pedido demasiado grande.',413);
 if(body.action==='login'){const ip=crypto.createHash('sha256').update(String(req.headers['x-forwarded-for']||'unknown').split(',')[0]).digest('hex');const now=Date.now();for(const [key,v] of attempts)if(v.until<now)attempts.delete(key);const rate=attempts.get(ip)||{count:0,until:now+900000};if(rate.count>=5){res.setHeader('Retry-After',Math.ceil((rate.until-now)/1000));return send(429,{error:'Demasiadas tentativas. Tente novamente em 15 minutos.'});}if(!passwordMatches(body.password)){rate.count++;if(attempts.size<2048)attempts.set(ip,rate);await new Promise(r=>setTimeout(r,750));return send(401,{error:'Palavra-passe incorrecta.'});}attempts.delete(ip);const data=Buffer.from(JSON.stringify({exp:now+8*3600000,nonce:crypto.randomBytes(16).toString('hex')})).toString('base64url');res.setHeader('Set-Cookie','__Host-ts_admin='+data+'.'+sign(data)+'; HttpOnly; Secure; SameSite=Strict; Path=/; Max-Age=28800');return send(200,{ok:true});}
 if(!session(req))return send(401,{error:'A sessão terminou. Entre novamente. O seu rascunho continua neste navegador.'});if(body.action==='logout'){res.setHeader('Set-Cookie','__Host-ts_admin=; HttpOnly; Secure; SameSite=Strict; Path=/; Max-Age=0');return send(200,{ok:true});}if(body.action==='publish')return send(200,await publish(body));return send(400,{error:'Acção inválida.'});}catch(e){return send(e.status||500,{error:e.status?e.message:'Não foi possível guardar. O rascunho foi mantido; tente novamente.'});}};
